665		} else if classifyLocalSettings(ctx, localSettingsFileAbs) == localTracked {
666			// Dropped only on PROOF that the file is tracked. Discarding every
667			// local setting because a repository could not be read would be a
668			// worse failure than the one being guarded against — the exec-bearing
669			// OPF command applies the stricter policy for itself.
670			settings.localLayerRejection = localLayerTrackedReason
671			localData = nil
672		} else if err := mergeJSON(settings, localData); err != nil {
673			return nil, fmt.Errorf("merging local settings: %w", err)
674		}
