560	// Load loads the Entire settings from .entire/settings.json, then applies
561	// clone-local preferences from the git common dir, then applies any overrides
562	// from .entire/settings.local.json if it exists.
563	// Returns default settings if no settings or preferences file exists.
564	// Works correctly from any subdirectory within the repository.
565	func Load(ctx context.Context) (*EntireSettings, error) {
566		if worktreeRoot, ok := worktreeRootFromContext(ctx); ok {
567			return loadForWorktreeRoot(ctx, worktreeRoot)
568		}
569	
570		settingsFileAbs, localSettingsFileAbs, err := settingsAbsPaths(ctx)
571		if err != nil {
572			return nil, err
573		}
574		preferencesFileAbs := ""
575		if path, prefErr := ClonePreferencesPath(ctx); prefErr == nil {
576			preferencesFileAbs = path
577		} else {
578			// Log at Debug rather than silently dropping the preferences layer.
579			// "Not in a git repo" is a legitimate case (some commands run outside
580			// a repo), but a git PATH issue or .git/ permission failure is worth
581			// finding via `ENTIRE_LOG_LEVEL=debug` when users report "my picker
582			// choices vanished".
583			logging.Debug(ctx, "clone preferences path unresolved; skipping preferences layer",
