590	// settingsAbsPaths resolves the base and local settings file paths against the
591	// repository anchor. Resolution failures are returned rather than converted to
592	// cwd-relative paths: doing the latter can select a different .entire from a
593	// subdirectory precisely when Git could not establish which repository owns it.
594	func settingsAbsPaths(ctx context.Context) (base, local string, err error) {
595		// entiredir.PathTo, not paths.AbsPath: both files live under .entire, and
596		// entiredir owns the one anchor for that directory. AbsPath's failure mode
597		// here was a relative path that then resolved against the process's own
598		// directory, which is the thing the anchor exists to prevent.
599		base, err = entiredir.PathTo(ctx, EntireSettingsFile)
600		if err != nil {
601			return "", "", fmt.Errorf("resolve project settings path: %w", err)
602		}
603		local, err = entiredir.PathTo(ctx, EntireSettingsLocalFile)
604		if err != nil {
605			return "", "", fmt.Errorf("resolve local settings path: %w", err)
606		}
607		return base, local, nil
608	}
