 219		TrailsEnabledAPIBase   string     `json:"trails_enabled_api_base,omitempty"`
 220		TrailsEnabledAuthKey   string     `json:"trails_enabled_auth_key,omitempty"`
 221	
 222		// Agent-help refresh failures use a separate, short-lived backoff. Keeping
 223		// this out of TrailsEnabled ensures a transient help-command failure cannot
 224		// suppress SessionStart's authoritative enablement probe or context injection.
 225		TrailsAgentHelpRefreshFailedAt *time.Time `json:"trails_agent_help_refresh_failed_at,omitempty"`
