1006	// unrooted write: the callers that reach it name a file directly (explicit-path
1007	// tests, and `entire disable` in a directory with no repository), and there is
1008	// no boundary to enforce for a path the caller chose itself.
1009	func writeClonePreferencesAtomic(filePath string, data []byte, perm fs.FileMode) error {
1010		root, name, err := clonePreferencesRoot(filePath)
1011		if err != nil {
