1025	// loadFromFile loads settings from a specific file path.
1026	// Returns default settings if the file doesn't exist.
1027	func loadFromFile(filePath string) (*EntireSettings, error) {
1028		settings := &EntireSettings{
1029			Enabled: true, // Default to enabled
1030		}
1031	
1032		data, err := readConfined(filePath)
1033		if err != nil {
1034			if errors.Is(err, fs.ErrNotExist) {
1035				return settings, nil
1036			}
1037			return nil, fmt.Errorf("%w", err)
1038		}
1039	
1040		dec := json.NewDecoder(bytes.NewReader(data))
1041		dec.DisallowUnknownFields()
1042		if err := dec.Decode(settings); err != nil {
1043			return nil, fmt.Errorf("parsing settings file: %w", err)
1044		}
1045	
1046		// Validate commit_linking if set
1047		if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
1048			return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
1049		}
1050	
1051		// SummaryGeneration is NOT validated here — individual files may
1052		// legitimately contain only a model (provider comes from another file).
1053		// Validation happens after merge in Load().
1054	
1055		if settings.Redaction != nil {
1056			if err := validateOPFSettings(settings.Redaction.OpenAIPrivacyFilter); err != nil {
1057				return nil, err
1058			}
1059		}
1060	
1061		return settings, nil
1062	}
1063	
1064	func loadClonePreferencesFromFile(filePath string) (*ClonePreferences, error) {
1065		prefs := &ClonePreferences{}
1066	
1067		data, err := readConfined(filePath)
1068		if err != nil {
1069			if errors.Is(err, fs.ErrNotExist) {
1070				return prefs, nil
1071			}
1072			return nil, fmt.Errorf("%w", err)
1073		}
1074	
1075		// Lenient decoding here (vs. strict via DisallowUnknownFields in
1076		// loadFromFile for EntireSettings). Two reasons clone preferences need
1077		// the looser contract:
1078		//   1. They are rewritten on every picker save — a newer binary can
1079		//      introduce a field the older binary then sees as unknown, which
1080		//      under strict decoding would brick settings.Load for that older
1081		//      binary across the whole clone.
1082		//   2. The file lives in .git/, so users rarely hand-edit it; the
1083		//      typo-silently-ignored downside is theoretical here.
1084		// EntireSettings stays strict because it's committed and team-edited,
1085		// where unknown keys usually mean typos worth surfacing immediately.
1086		if err := json.Unmarshal(data, prefs); err != nil {
1087			return nil, fmt.Errorf("parsing preferences file: %w", err)
1088		}
1089		return prefs, nil
1090	}
1091	
1092	func saveClonePreferencesToFile(prefs *ClonePreferences, filePath string) error {
1093		if prefs == nil {
1094			prefs = &ClonePreferences{}
1095		}
1096		data, err := jsonutil.MarshalIndentWithNewline(prefs, "", "  ")
1097		if err != nil {
1098			return fmt.Errorf("marshaling preferences: %w", err)
1099		}
1100	
1101		if err := writeClonePreferencesAtomic(filePath, data, 0o644); err != nil {
1102			return fmt.Errorf("writing preferences file: %w", err)
1103		}
1104		return nil
1105	}

